module.exports = {
    onAction: function(transport, actionId, params) {
        var method = (params.method || "GET").toUpperCase();
        var uri = params.uri || "/";
        var headers = {};
        if (params.auth_token) {
            headers["Authorization"] = "Bearer " + params.auth_token;
        }
        if (method === "GET") {
            return engine.http.get(uri, headers).then(function(res) {
                engine.setVariable("rest_last_status", String(res.status));
                return "Status " + res.status + " (" + res.data.length + " bytes)";
            });
        } else {
            return engine.http.post(uri, params.body || "", headers).then(function(res) {
                engine.setVariable("rest_last_status", String(res.status));
                return "Status " + res.status + " (" + res.data.length + " bytes)";
            });
        }
    }
};
